delete from public.exercises where grammar_topic_id in (select id from public.grammar_topics where slug in ('passive-reporting', 'future-in-the-past', 'advanced-relative-clauses', 'cause-and-result-linkers', 'hedging', 'conditionals-without-if', 'dependent-prepositions', 'discourse-markers'));

insert into public.grammar_lessons (grammar_topic_id, title_he, body_md, cefr_level, sort_order)
select gt.id, l.title_he, l.body_md, gt.cefr_level, 1
from public.grammar_topics gt
join (values
  ('passive-reporting', 'It is said that... / He is believed to...', $$בכתיבה רשמית ובחדשות מוסרים מידע בלי לומר מי אמר אותו. יש לזה שני מבנים, עם פעלים כמו say, believe, think, report, expect, consider, know.

**מבנה 1: It + is/was + צורה שלישית + that**

- **It is said that** the company will close two branches.
- **It was reported that** three people were injured.

**מבנה 2: נושא + is/was + צורה שלישית + to**

- The company **is said to be** in financial trouble.
- He **is believed to live** abroad.

**כשמדברים על העבר בתוך המשפט:** to have + צורה שלישית.

- The painting **is thought to have been** stolen in 1990.
- She **is said to have left** the country last year.

**השוו:**

- People say that he is very rich. (רגיל)
- **It is said that** he is very rich. (רשמי)
- **He is said to be** very rich. (רשמי ותמציתי)

**שימו לב:** אחרי מבנה 2 בא to, לא that: He is said **to be** rich (לא He is said that he is rich).$$),
  ('future-in-the-past', 'I was going to call you: עתיד מנקודת מבט של עבר', $$לפעמים מדברים על העבר, ובתוכו על משהו שעוד היה **לפניו**. במקרה כזה will הופך ל-**would**, ו-am going to הופך ל-**was going to**.

**would:** תחזית או הבטחה מנקודת מבט של עבר.

- I knew she **would** love the gift.
- He promised he **would** call, but he didn't.

**was / were going to:** תוכנית שהייתה, ולעתים קרובות לא יצאה לפועל.

- I **was going to** call you, but my phone died.
- We **were going to** move to Haifa, but we changed our minds.

**was / were about to:** משהו שעמד לקרות ממש באותו רגע.

- I **was about to** leave when the phone rang.

**was / were to:** בכתיבה וסיפור, מה שקרה בסוף, בדיעבד.

- It was a small café. Nobody knew it **was to** become the most famous restaurant in town.

**שימו לב:** אחרי כל המבנים האלה באה צורת בסיס: was going to **call**, would **love**, was about to **leave**.$$),
  ('advanced-relative-clauses', 'whom, whose, in which: זיקה בכתיבה רשמית', $$מעבר ל-who, which ו-that, בכתיבה רשמית יש עוד כמה כלים.

**whom:** במקום who כשהאדם הוא המושא, בעיקר אחרי מילת יחס.

- The manager **to whom** I spoke was very helpful.
- She thanked everyone **with whom** she had worked.

**whose:** שייכות, לאנשים וגם לדברים.

- The writer **whose** book won the prize is only 25.
- It's a city **whose** history goes back 3,000 years.

**מילת יחס + which:** במקום להשאיר את מילת היחס בסוף.

- The house **in which** I grew up was sold. (רשמי)
- The house **which** I grew up **in** was sold. (פחות רשמי)

**כמות + of whom / of which:**

- I have three brothers, **two of whom** live abroad.
- She wrote ten books, **most of which** were translated.

**שימו לב:** אחרי מילת יחס לא משתמשים ב-that או ב-who: **to whom** (לא to who), **in which** (לא in that).$$),
  ('cause-and-result-linkers', 'because of, owing to, consequently: סיבה ותוצאה בכתיבה', $$כמו במילות הניגוד, גם כאן כל מילה באה עם מבנה אחר.

**סיבה + שם עצם (לא משפט שלם):**

- **because of / due to / owing to** + שם עצם
- The flight was cancelled **due to** the storm.
- **Owing to** a lack of funds, the project was stopped.

**סיבה + משפט שלם:**

- **because / since / as** + נושא + פועל
- **Since** it was late, we took a taxi.

**תוצאה, בין שני משפטים נפרדים** (באות בתחילת המשפט השני, ואחריהן פסיק):

- **Therefore / Consequently / As a result,**
- Sales fell sharply. **Consequently,** 200 workers lost their jobs.

**תוצאה, באותו משפט:** **so** + משפט.

- It was raining, **so** we stayed home.

**שימו לב:**

- לא due to the fact it was raining. נכון: **due to the fact that** it was raining (שם עצם + that).
- **therefore** לא מחבר שני משפטים עם פסיק בלבד. נכון: Prices rose; **therefore,** demand fell. או שני משפטים נפרדים.$$),
  ('hedging', 'It would seem that... : לטעון בזהירות', $$בכתיבה אקדמית ומקצועית נמנעים מטענות מוחלטות כשהראיות לא מוחלטות. הריכוך הזה נקרא hedging, והוא סימן לכתיבה בוגרת ולא לחוסר ביטחון.

**פעלים מודליים:** may, might, could

- This **may** explain the drop in sales.

**פעלים מרככים:** seem, appear, suggest, tend to

- The results **suggest** that sleep affects memory.
- Young people **tend to** change jobs more often.

**מבנים עם it:**

- **It would seem that** the policy has failed.
- **It is likely / possible that** prices will rise.

**תארים ותארי פועל:** arguably, apparently, probably, to some extent, in most cases

- This is **arguably** the best novel of the decade.
- The plan worked **to some extent**.

**השוו:**

- Social media causes loneliness. (מוחלט, וקשה להוכיח)
- Social media **may contribute to** loneliness **in some cases**. (מדויק יותר)

**שימו לב:** לא לרכך כל משפט. עובדה ידועה נאמרת בפשטות: Water boils at 100°C.$$),
  ('conditionals-without-if', 'Were I, Had she, Should you: תנאי בהיפוך', $$בכתיבה רשמית אפשר להשמיט את if ולהקדים את פועל העזר לפני הנושא. המשמעות לא משתנה.

**תנאי שני (were):**

- If I were in your position... → **Were I** in your position, I would accept.

**תנאי שלישי (had):**

- If she had known... → **Had she** known, she would have helped.

**תנאי ראשון רשמי (should):**

- If you have any questions... → **Should you** have any questions, please contact us.

**שלילה:** not בא אחרי הנושא, ולא מתקצרים.

- **Had we not** left early, we would have missed the train. (לא Hadn't we)

**חלופות ל-if:** provided (that), as long as, unless, in case, supposing

- You can borrow the car **provided that** you return it by six.
- **Unless** it rains, we'll eat outside. (= if it doesn't rain)

**שימו לב:** ההיפוך עובד רק עם were, had ו-should. לא Did you know..., would... בתור תנאי.$$),
  ('dependent-prepositions', 'interested in, dependent on: מילת היחס שבאה עם המילה', $$הרבה פעלים, שמות תואר ושמות עצם באים עם מילת יחס קבועה. אין חוק שמסביר אותה, ולכן לומדים אותן יחד עם המילה. כאן בעיקר אלה שבהן דוברי עברית טועים, כי בעברית מילת היחס שונה.

**פעלים:**

- depend **on** (תלוי ב-, לא depend of)
- consist **of** (מורכב מ-)
- insist **on** (מתעקש על)
- object **to** + ing (מתנגד ל-): I object **to being** treated like this.
- succeed **in** + ing (מצליח ל-): She succeeded **in finding** a job.

**שמות תואר:**

- responsible **for** (אחראי על, לא on)
- aware **of** (מודע ל-)
- capable **of** (מסוגל ל-)
- keen **on** (מתלהב מ-)

**שמות עצם:**

- an increase **in** prices (עלייה ב-)
- a solution **to** the problem (פתרון ל-, לא for)
- a reason **for** the delay
- an advantage **of** / **over**

**שימו לב:** אחרי מילת יחס תמיד בא ing: interested in **learning**, capable of **doing**.$$),
  ('discourse-markers', 'Moreover, nevertheless, that said: לחבר טיעון', $$סמני שיח מראים לקורא איך משפט קשור למשפט הקודם: מוסיף, מנגיד, מסכם או מדגים. בכתיבה טובה הם מדויקים ולא מופיעים בכל משפט.

**הוספה:** Moreover, Furthermore, In addition, What is more

- The plan is expensive. **Moreover,** it would take years.

**ניגוד:** However, Nevertheless, That said, On the other hand

- The results were promising. **That said,** the sample was small.
- **Nevertheless** מתאים כשהמסקנה נשארת למרות הקושי: It was risky. **Nevertheless,** they went ahead.

**הדגמה:** For instance, For example, To illustrate

**חיזוק וחידוד:** Indeed, In fact, In other words

- The policy failed. **Indeed,** unemployment rose.

**סיכום:** In short, Overall, To sum up, All in all

**שימו לב:**

- **On the other hand** בא אחרי טיעון בצד אחד (גם אם לא כתבו On the one hand).
- **Besides** פחות רשמי מ-Moreover.
- אחרי סמן שיח בתחילת משפט בא פסיק.$$)
) as l(slug, title_he, body_md) on gt.slug = l.slug;

insert into public.exercises (type, skill_area, grammar_topic_id, cefr_level, content, sort_order)
select 'fill_blank'::exercise_type, 'grammar'::skill_area, gt.id, gt.cefr_level, gen.content::jsonb, gen.sort_order
from (values
  ('passive-reporting', '{"sentence":"It ___ reported that the minister will resign.","correctAnswer":"is","hint":"It is reported that"}', 1),
  ('passive-reporting', '{"sentence":"The castle is believed ___ built in the 12th century.","correctAnswer":"to have been","hint":"עבר בתוך המשפט: to have been"}', 2),
  ('passive-reporting', '{"sentence":"She is said ___ speak five languages.","correctAnswer":"to","hint":"נושא + is said + to"}', 3),
  ('passive-reporting', '{"sentence":"It ___ expected that prices will rise next year.","correctAnswer":"is","hint":"It is expected that"}', 4),
  ('passive-reporting', '{"sentence":"The suspect is thought ___ left the country.","correctAnswer":"to have","hint":"פעולה שכבר קרתה: to have + צורה שלישית"}', 5),
  ('future-in-the-past', '{"sentence":"I ___ going to tell you, but I forgot.","correctAnswer":"was","hint":"תוכנית שלא יצאה לפועל"}', 1),
  ('future-in-the-past', '{"sentence":"She promised she ___ help us with the move.","correctAnswer":"would","hint":"will מנקודת מבט של עבר"}', 2),
  ('future-in-the-past', '{"sentence":"We were ___ to go out when it started to rain.","correctAnswer":"about","hint":"עמד לקרות באותו רגע"}', 3),
  ('future-in-the-past', '{"sentence":"They were going ___ buy a house, but prices went up.","correctAnswer":"to","hint":"was/were going to"}', 4),
  ('future-in-the-past', '{"sentence":"Nobody guessed that the young singer ___ to become a star.","correctAnswer":"was","hint":"was to: מה שקרה בסוף"}', 5),
  ('advanced-relative-clauses', '{"sentence":"The person ___ whom I sent the email never replied.","correctAnswer":"to","hint":"מילת יחס לפני whom"}', 1),
  ('advanced-relative-clauses', '{"sentence":"That''s the artist ___ paintings sold for millions.","correctAnswer":"whose","hint":"שייכות"}', 2),
  ('advanced-relative-clauses', '{"sentence":"The village in ___ they live has no school.","correctAnswer":"which","hint":"מילת יחס + which"}', 3),
  ('advanced-relative-clauses', '{"sentence":"He has many friends, most of ___ he met at university.","correctAnswer":"whom","hint":"כמות + of whom"}', 4),
  ('advanced-relative-clauses', '{"sentence":"The reasons for ___ she left were never explained.","correctAnswer":"which","hint":"מילת יחס + which"}', 5),
  ('cause-and-result-linkers', '{"sentence":"The match was postponed ___ to heavy rain.","correctAnswer":"due","hint":"due to + שם עצם"}', 1),
  ('cause-and-result-linkers', '{"sentence":"___ it was a holiday, the shops were closed.","correctAnswer":"Since","hint":"סיבה + משפט שלם"}', 2),
  ('cause-and-result-linkers', '{"sentence":"The company lost its biggest client. ___, it had to cut costs.","correctAnswer":"Consequently","hint":"תוצאה במשפט נפרד"}', 3),
  ('cause-and-result-linkers', '{"sentence":"Owing ___ the strike, there were no trains.","correctAnswer":"to","hint":"owing to + שם עצם"}', 4),
  ('cause-and-result-linkers', '{"sentence":"I was tired, ___ I went to bed early.","correctAnswer":"so","hint":"תוצאה באותו משפט"}', 5),
  ('hedging', '{"sentence":"The data ___ that the treatment is effective, but more research is needed.","correctAnswer":"suggests","hint":"פועל מרכך"}', 1),
  ('hedging', '{"sentence":"It would ___ that the meeting has been cancelled.","correctAnswer":"seem","hint":"It would seem that"}', 2),
  ('hedging', '{"sentence":"This is ___ the most important discovery of the century.","correctAnswer":"arguably","hint":"תואר פועל מרכך"}', 3),
  ('hedging', '{"sentence":"Older drivers ___ to drive more carefully.","correctAnswer":"tend","hint":"tend to"}', 4),
  ('hedging', '{"sentence":"It is ___ that the company will announce layoffs.","correctAnswer":"likely","hint":"It is likely that"}', 5),
  ('conditionals-without-if', '{"sentence":"___ I known about the problem, I would have told you.","correctAnswer":"Had","hint":"תנאי שלישי בהיפוך"}', 1),
  ('conditionals-without-if', '{"sentence":"___ you need any help, do not hesitate to call.","correctAnswer":"Should","hint":"תנאי ראשון רשמי"}', 2),
  ('conditionals-without-if', '{"sentence":"___ she the manager, she would change the rules.","correctAnswer":"Were","hint":"תנאי שני בהיפוך"}', 3),
  ('conditionals-without-if', '{"sentence":"Had we ___ booked in advance, there would have been no tickets.","correctAnswer":"not","hint":"שלילה אחרי הנושא"}', 4),
  ('conditionals-without-if', '{"sentence":"You can join the trip ___ that you bring your own equipment.","correctAnswer":"provided","hint":"provided that"}', 5),
  ('dependent-prepositions', '{"sentence":"The final decision depends ___ the budget.","correctAnswer":"on","hint":"depend on"}', 1),
  ('dependent-prepositions', '{"sentence":"Who is responsible ___ this mistake?","correctAnswer":"for","hint":"responsible for"}', 2),
  ('dependent-prepositions', '{"sentence":"We need a solution ___ the parking problem.","correctAnswer":"to","hint":"a solution to"}', 3),
  ('dependent-prepositions', '{"sentence":"She succeeded ___ convincing the board.","correctAnswer":"in","hint":"succeed in + ing"}', 4),
  ('dependent-prepositions', '{"sentence":"The team consists ___ eight engineers.","correctAnswer":"of","hint":"consist of"}', 5),
  ('discourse-markers', '{"sentence":"The hotel was expensive. ___, the service was poor.","correctAnswer":"Moreover","hint":"הוספה"}', 1),
  ('discourse-markers', '{"sentence":"The data looks convincing. That ___, the study was very small.","correctAnswer":"said","hint":"That said: ניגוד מרוכך"}', 2),
  ('discourse-markers', '{"sentence":"It was a huge risk. ___, they decided to invest.","correctAnswer":"Nevertheless","hint":"המסקנה נשארת למרות הקושי"}', 3),
  ('discourse-markers', '{"sentence":"The project was late and over budget. In ___, it was a failure.","correctAnswer":"short","hint":"סיכום"}', 4),
  ('discourse-markers', '{"sentence":"Some cities have cut car use. ___ instance, Oslo banned cars from its centre.","correctAnswer":"For","hint":"הדגמה"}', 5)
) as gen(slug, content, sort_order)
join public.grammar_topics gt on gt.slug = gen.slug;

insert into public.exercises (type, skill_area, grammar_topic_id, cefr_level, content, sort_order)
select 'reorder'::exercise_type, 'grammar'::skill_area, gt.id, gt.cefr_level, gen.content::jsonb, gen.sort_order
