  ('advanced-relative-clauses', '{"tokens":["The","doctor","with","whom","I","spoke","was","very","kind"],"correctOrder":[0,1,2,3,4,5,6,7,8]}', 100),
  ('advanced-relative-clauses', '{"tokens":["I","read","two","reports","both","of","which","were","useful"],"correctOrder":[0,1,2,3,4,5,6,7,8]}', 101),
  ('cause-and-result-linkers', '{"tokens":["The","road","was","closed","because","of","the","snow"],"correctOrder":[0,1,2,3,4,5,6,7]}', 100),
