-- Check: how many topics, lessons and exercises this seed now has.
select
  (select count(*) from public.grammar_topics where slug in ('passive-reporting', 'future-in-the-past', 'advanced-relative-clauses', 'cause-and-result-linkers', 'hedging', 'conditionals-without-if', 'dependent-prepositions', 'discourse-markers')) as topics,
  (select count(*) from public.grammar_lessons gl join public.grammar_topics gt on gt.id = gl.grammar_topic_id where gt.slug in ('passive-reporting', 'future-in-the-past', 'advanced-relative-clauses', 'cause-and-result-linkers', 'hedging', 'conditionals-without-if', 'dependent-prepositions', 'discourse-markers')) as lessons,
  (select count(*) from public.exercises e join public.grammar_topics gt on gt.id = e.grammar_topic_id where gt.slug in ('passive-reporting', 'future-in-the-past', 'advanced-relative-clauses', 'cause-and-result-linkers', 'hedging', 'conditionals-without-if', 'dependent-prepositions', 'discourse-markers')) as exercises;
